entries[231280] = { ["name"] = "Wushoolays Amulett der Natur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Druide\nBenötigt Stufe 60\nBenutzen: Bringt den Druiden in Einklang mit der Natur. Erhöht 20 Sek. lang den verursachten Schaden durch Zauber um 10%, verbessert Heileffekte um 10% und erhöht die kritische Trefferchance von Zaubern um 10%. (2 Min Abklingzeit)\n\nGewand des Haruspex (0/5)\nHaruspex' Zandalariarmschienen\nHaruspex' Zandalarigürtel\nHaruspex' Zandalaritunika\nReiner verzauberter Südmeertang\nWushoolays Amulett der Natur\n(2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Zauberzeit und globale Abklingzeit von 'Sternenfeuer' um 0.5 Sek.\n(5) Set : Erhöht die kritische Trefferchance von 'Zorn' um 10%." }
entries[231281] = { ["name"] = "Wushoolays Amulett der Geister", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Schamane\nBenötigt Stufe 60\nBenutzen: Erhöht den Schaden Eures Zaubers 'Blitzschlagschild' um 100%. Hält 20 Sek. lang an. (2 Min Abklingzeit)\n\nOrnat des Weissagers (0/5)\nArmschienen des Zandalariweissagers\nGürtel des Zandalariweissagers\nHalsberge des Zandalariweissagers\nUnversehrte Vision von Voodress\nWushoolays Amulett der Geister\n(2) Set : Erhöhte Verteidigung +7.\n(3) Set : Erhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 10%.\n(5) Set : Erhöht die Chance, dass Eure Rune 'Kraftwoge' ausgelöst wird, um zusätzliche 5%." }
entries[231282] = { ["name"] = "Hazza'rahs Amulett der frostigen Magie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Erhöht die kritische Trefferchance von 'Frostblitz', 'Zauberfrostblitz' und 'Gefrorene Kugel' um 5% und erhöht den kritischen Trefferschaden von 'Frostblitz', 'Zauberfrostblitz' und 'Gefrorene Kugel' um 50%. Hält 20 Sek. lang an. (2 Min Abklingzeit)\n\nRoben des Illusionisten (0/5)\nRobe des Zandalari-Illusionisten\nMantel des Zandalari-Illusionisten\nHandlappen des Zandalari-Illusionisten\nJuwel von Kajaro\nHazza'rahs Amulett der frostigen Magie\n(2) Set : Erhöht den von Frostzaubern und -effekten verursachten Schaden um bis zu 14.\n(3) Set : Erhöht die Chance, dass Eure Rune 'Eisige Finger' ausgelöst wird, um zusätzliche 15%.\n(5) Set : Erhöht den verursachten Schaden Eurer Zauber 'Frostblitz' und 'Zauberfrostblitz' um 75%." }
entries[231283] = { ["name"] = "Hazza'rahs Amulett des Schutzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\nBenutzen: Verringert die Zauberzeit von 'Große Heilung' um 40%, verringert die Manakosten Eurer Heilzauber um 5% und 'Sühne' trifft bis zu 2 zusätzliche Ziele, wenn es auf Verbündete gewirkt wird. Hält 15 Sek. lang an. (1 Min, 30 Sek. Abklingzeit)\n\nGewandung des Glaubenshüters (0/5)\nHandlappen des Zandalariglaubenshüters\nBindungen des Zandalariglaubenshüters\nMantel des Zandalariglaubenshüters\nDas allsehende Auge von Zuldazar\nHazza'rahs Amulett des Schutzes\n(2) Set : Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 22 und den verursachten Schaden um bis zu 7.\n(3) Set : Verringert die Abklingzeit Eures Zaubers 'Sühne' um 6 Sek.\n(5) Set : Erhöht den von Eurem Zauber 'Machtwort: Schild' absorbierten Schaden um 10%." }
entries[231284] = { ["name"] = "Hazza'rahs Amulett der Zerstörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Erhöht Eure kritische Trefferchance um 10% und die Angriffsgeschwindigkeit Eures Begleiters um 50%. Hält 20 Sek. lang an. Dieser Zauber wirkt sich nicht auf temporäre Begleiter oder unterworfene Dämonen aus. (2 Min Abklingzeit)\n\nRoben des Besessenen (0/5)\nMantel des Zandalaribesessenen\nRobe des besessenen Zandalari\nHandlappen des Zandalaribesessenen\nKezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\n(2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht die Angriffskraft und den Zauberschaden, den Euer Dämon durch Eure Attribute erlangt, um 20%.\n(5) Set : Erhöht die Vorteile Eures Talents 'Meister der Dämonologie' um 50%." }
entries[231285] = { ["name"] = "Gri'leks Amulett der Ehre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Paladin\nBenötigt Stufe 60\nBenutzen: Erhöht die kritische Trefferchance von Heiligzaubern 15 Sek. lang um 10%. Gewährt zusätzliche 5%, wenn 'Schockierende Ehrfurcht' eingraviert ist. (1 Min, 30 Sek. Abklingzeit)\n\nRüstung des Freidenkers (0/5)\nBrustplatte des Zandalarifreidenkers\nGürtel des Zandalarifreidenkers\nArmschützer des Zandalarifreidenkers\nGri'leks Amulett der Ehre\nEmblem des Helden\n(2) Set : Erhöht den von Heiligzaubern und -effekten verursachten Schaden um bis zu 14.\n(3) Set : Erhöht den verursachten Schaden Eures Zaubers 'Heiliger Schock' um 50%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Exorzismus' um 3 Sek. und erhöht dessen verursachten Schaden um 75%." }
