entries[231378] = { ["name"] = "Schimmernde goldene Scheibe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Krieger\nBenötigt Stufe 60\n\"Eine flache Scheibe aus warmem goldenen Metall. Die runde Oberfläche ist fast vollkommen glatt, aber wenn Ihr mit den Fingerspitzen darüberfahrt, könnt Ihr winzige Vertiefungen und Unreinheiten spüren. Was für ein seltsamer Gegenstand.\"" }
