entries[231385] = { ["name"] = "Simulakrum der Drachenseele", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Tragt das Mal eines drachischen Boten, eines Dragonflight-Verbündeten.\n\"Das Simulakrum wurde verzaubert, um den Träger als Freund des roten Drachenschwarms auszuzeichnen.\"" }
entries[231386] = { ["name"] = "Makellose schwarze Drachenschuppe", ["text"] = "Questgegenstand\nEinzigartig\nKlassen: Krieger\nBenötigt Stufe 60\n\"Die Schuppe ist riesig und makellos. Nur die majestätischsten Drachen tragen Schuppen solcher Güte.\"" }
entries[231387] = { ["name"] = "Sturmzorn, geheiligte Kurzklinge des Windsuchers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Dolch\n45 - 113 Schaden Tempo 1.90\n(41.58 Schaden pro Sekunde)\n+10 Ausdauer\n+9 Intelligenz\n+7 Willenskraft\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 68.\nAnlegen: Schaden verursachende Zauber, die keinen regelmäßigen Schaden verursachen, haben eine Chance, bis zu 3 Zielen 181 bis 229 Schaden zuzufügen. (Procchance: 10%, 100ms Abklingzeit)" }
entries[231452] = { ["name"] = "Blut des Lichtbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Paladin\nBenötigt Stufe 60\n\"Dieses kleine Reliquiar ist mit einer Blutprobe gefüllt. Auf der Unterseite befindet sich ein teilweise abgerissenes Pergamentetikett mit der Aufschrift \"Uther\".\"" }
entries[231460] = { ["name"] = "Ebenenbrecher von Azgaloth", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n146 - 270 Schaden Tempo 3.60\n(57.78 Schaden pro Sekunde)\n+31 Ausdauer\n+32 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 90 und den verursachten Schaden um bis zu 30." }
entries[231466] = { ["name"] = "Kodex des Pechschwingenhexenmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60" }
entries[231509] = { ["name"] = "Cassandras Foliant", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Priester\nBenötigt Stufe 60\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 47.\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 70.\nBenutzen: Lest eine Prophezeiung aus dem Folianten, was die kritische Trefferchance Eures nächsten Angriffs oder Zaubers, der keinen regelmäßigen Schaden verursacht, um 100% erhöht. (2 Min Abklingzeit)" }
entries[231512] = { ["name"] = "Urzeitlicher Hakkarigötze", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 58\n\"Etwas uraltes Böses lauert in diesem Götzen...\"" }
