entries[231753] = { ["name"] = "Trost des Himmelswalls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Streitkolben\n50 - 124 Schaden Tempo 2.10\n(41.43 Schaden pro Sekunde)\n+8 Ausdauer\n+16 Intelligenz\n+10 Willenskraft\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 128 und den verursachten Schaden um bis zu 43." }
entries[231754] = { ["name"] = "Turmfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n123 - 229 Schaden Tempo 2.90\n(60.69 Schaden pro Sekunde)\n+14 Beweglichkeit\nHaltbarkeit 105 / 105\nKlassen: Jäger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nTrefferchance: Erhöht die Laufgeschwindigkeit 10 Sek. lang um 40%.\n\"Diese schwere, gekrümmte Klinge trägt die Macht eines Jagdfalken in sich. Wie ein Turmfalke rast sie mit unglaublichem Eifer auf ihre Beute zu.\"" }
entries[231755] = { ["name"] = "Wanderfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n123 - 229 Schaden Tempo 2.90\n(60.69 Schaden pro Sekunde)\n+9 Beweglichkeit\nHaltbarkeit 105 / 105\nKlassen: Jäger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nTrefferchance: Gewährt sofort 1 zusätzlichen Angriff mit beiden Waffen.\n\"Diese schwere, gekrümmte Klinge trägt die Macht eines Jagdfalken in sich. Wie ein Wanderfalke schlägt sie schnell zu.\"" }
entries[231777] = { ["name"] = "Kristallisierte Qirajiextremität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nIn Schildhand geführt\n+8 Ausdauer\n+9 Willenskraft\nBenötigt Stufe 60\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 55 und den verursachten Schaden um bis zu 19." }
entries[231778] = { ["name"] = "Bergquellwasser", ["text"] = "Herbeigezauberter Gegenstand\nBenötigt Stufe 55\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 5100 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[231779] = { ["name"] = "Zorn des Wray", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+10 Naturwiderstand\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nBenutzen: Erhöht Eure Stärke 20 Sek. lang um 92. (2 Min Abklingzeit)" }
entries[231780] = { ["name"] = "Foliant des Wasserherbeizauberns VIII", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenötigt Stufe 60\nZaubert 20 Flaschen Bergquellwasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt.\n\"Lehrt Euch 'Wasser herbeizaubern' (Rang 8).\"" }
entries[231781] = { ["name"] = "Seele des Donners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+20 Naturwiderstand\nBenötigt Stufe 60\nBenutzen: Wirft 5 Sek. lang Naturzauber auf den Zaubernden zurück. (5 Min Abklingzeit)" }
