entries[231828] = { ["name"] = "Rune der Meditationsspezialisierung", ["text"] = "Accountgebunden\nEinzigartig\nKlassen: Paladin , Jäger , Priester , Schamane , Magier , Hexenmeister , Druide\nPrägt Euren Ring mit der Rune 'Meditationsspezialisierung':\n\nStellt alle 5 Sek. 5 Mana wieder her. Dieser Effekt ist nicht stapelbar mit anderen Ringrunen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[231829] = { ["name"] = "Rune der Heilungsspezialisierung", ["text"] = "Accountgebunden\nEinzigartig\nKlassen: Paladin , Priester , Schamane , Magier , Druide\nPrägt Euren Ring mit der Rune 'Heilungsspezialisierung':\n\nErhöht durch Zauber und Effekte verursachte Heilung um bis zu 26 Gesundheit. Dieser Effekt ist nicht stapelbar mit anderen Ringrunen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
