entries[231874] = { ["name"] = "Fangzahn von Venoxis", ["text"] = "Blutig\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Dolch\n33 - 72 Schaden Tempo 1.30\n(40.38 Schaden pro Sekunde)\n+8 Intelligenz\n+8 Willenskraft\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 36.\nAnlegen: Stellt alle 5 Sek. 6 Punkt(e) Mana wieder her." }
entries[231875] = { ["name"] = "Thekals Griff", ["text"] = "Blutig\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Faustwaffe\n94 - 175 Schaden Tempo 2.70\n(49.81 Schaden pro Sekunde)\n+14 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\nUrsegen (0/2)\nArlokks Griff\nThekals Griff\n(2) Set : Gewährt beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der wilden Götter erfüllt zu werden, was die Distanz- und Nahkampfangriffskraft 12 Sek. lang um 300 erhöht. (Procchance: 5%, 1.2Min. Abklingzeit)" }
entries[231876] = { ["name"] = "Zulianischer Schnitzler", ["text"] = "Blutig\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #663) (1)\nEinhändig Schwert\n66 - 123 Schaden Tempo 2.00\n(47.25 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nTrefferchance: Zerhäckselt den Gegner und verursacht 72 bis 96 Naturschaden.\nAnlegen: +12 Angriffskraft.\nAnlegen: Kürschnerei +10." }
entries[231882] = { ["name"] = "Unterdrückungsmaschinenbeleg", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nKlassen: Jäger\nBenötigt Stufe 60\n\"Beleg für Unterdrückungsmaschinenfallen. Von Van Amburgh an Brutwächter Dreschbringer.\"\n<Zum Lesen rechtsklicken>" }
entries[231885] = { ["name"] = "Frostgram", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n171 - 257 Schaden Tempo 3.60\n(59.44 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\nBenötigt Stufe 58\nAnlegen: Erhöht Bewegungstempo und Gesundheitsregenerationsrate." }
entries[231890] = { ["name"] = "Terrestris", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n2964 Rüstung\n55 Blocken\n+7 Ausdauer\n+8 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 20.\nAnlegen: Beschworene Totems gewähren einen Segen ihres Elements.\nBenutzen: Kühlt die Flammen von Terrestris und härtet ihn für die Verteidigung. (1 Min Abklingzeit)" }
entries[231891] = { ["name"] = "Abhandlung über den Gerfalken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenötigt Stufe 60\nDer Jäger nimmt den Aspekt eines Gerfalken an, wodurch sich seine Nah- und Distanzkampfangriffskraft um einen Wert in Höhe seines höchsten Rangs von 'Aspekt des Falken' erhöht.\n\nWährend 'Aspekt des Gerfalken' aktiv ist, kann das Talent 'Verbesserter Aspekt des Falken' nun von Nahkampfangriffen ausgelöst werden und diese stärken. Es kann immer nur jeweils ein Aspekt aktiv sein. (Procchance: 5%)\n\"Lehrt Euch 'Aspekt des Gerfalken'.\"" }
entries[231901] = { ["name"] = "Wahrheitsbringer", ["text"] = "Questgegenstand\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60" }
entries[231902] = { ["name"] = "Adas Amulett", ["text"] = "Wird beim Aufheben gebunden\nHals\n+21 Stärke\n+4 Ausdauer\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 7.\n\"Scheint aus Gebetsperlen und einem stark verkratzten Medaillon der Silbernen Hand gefertigt worden zu sein.\"" }
entries[231903] = { ["name"] = "Stofffetzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60\n\"Ein kleiner Stofffetzen von der Tunika von Uther dem Lichtbringer, auf dem sich ein paar Blutflecken befinden.\"" }
entries[231904] = { ["name"] = "Beflecktes Horn", ["text"] = "Questgegenstand\nEinzigartig\nBenötigt Stufe 50\nBenutzen: Stoßt ins Horn, um Aeonas zu Euch zurückzurufen, solltet Ihr von ihm getrennt werden. Alle magischen Verkleidungen, die auf Euch aktiv sind, werden abgebrochen. (15 Sek. Abklingzeit)" }
entries[231909] = { ["name"] = "Kristallisiertes Sternenlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Bringt Euch in Einklang mit dem Himmel, wodurch Ihr Eure Mondkingestalt durch ein erhabeneres Aussehen ersetzen könnt." }
entries[231910] = { ["name"] = "Herz von Azgaloth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 57\nAnlegen: Stellt alle 5 Sek. 36 Gesundheit wieder her.\nAnlegen: Stellt alle 5 Sek. 4 Punkt(e) Mana wieder her.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 35 und den verursachten Schaden um bis zu 12." }
