entries[231996] = { ["name"] = "Überladener Gobmogrifizierer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenutzen: Aktiviert dies im Pechschwingenhort auf dem Schwarzfels, um Euch als Techniker der Pechschwingen zu verkleiden. (5 Min Abklingzeit)" }
