entries[232262] = { ["name"] = "Brustschutz des Zorns", ["text"] = "Kerngeschmiedet\nWird beim Aufheben gebunden\nBrust Platte\n857 Rüstung\n+18 Stärke\n+11 Beweglichkeit\n+32 Ausdauer\n+10 Naturwiderstand\n+10 Frostwiderstand\nHaltbarkeit 165 / 165\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Verteidigung +10.\n\nUnbewegliche Macht (0/8)\nGürtel der Macht\nArmschienen der Macht\nBrustplatte der Macht\nStulpen der Macht\nHelm der Macht\nBeinplatten der Macht\nSchulterplatten der Macht\nSabatons der Macht\n(2) Set : Erhöht den Blockwert Eures Schildes um 30.\n(4) Set : Jedes Mal, wenn Ihr Schaden erleidet oder mit automatischen Angriffen Schaden verursacht, erzeugt Ihr zusätzlich 1 Wut.\n(6) Set : Erhöht Eure in der Verteidigungshaltung erzeugte Bedrohung um zusätzlich 10% und erhöht Euren in der Gladiatorhaltung verursachten Schaden um 4%." }
entries[232299] = { ["name"] = "Zulianischer Verteidiger", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n2468 Rüstung\n44 Blocken\n+8 Ausdauer\n+10 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 23." }
entries[232309] = { ["name"] = "Renatakis Seelenkanal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Schwert\n57 - 117 Schaden Tempo 2.10\n(41.43 Schaden pro Sekunde)\n+20 Willenskraft\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 23." }
entries[232310] = { ["name"] = "Renatakis Seelenkanal", ["text"] = "Blutig\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Schwert\n57 - 117 Schaden Tempo 2.10\n(41.43 Schaden pro Sekunde)\n+20 Willenskraft\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 23." }
entries[232311] = { ["name"] = "Zulianischer Tigerbalgumhang", ["text"] = "Wird beim Aufheben gebunden\nRücken\n50 Rüstung\n+17 Beweglichkeit\n+14 Ausdauer\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
entries[232312] = { ["name"] = "Blut des Lichtbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60\nBenutzen: Wendet das Blut des Lichtbringers auf Eure Waffe an, um sie zu weihen." }
entries[232324] = { ["name"] = "Vogelpfeife", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Pepe herbei, der es sich auf Eurem Kopf bequem macht, während Ihr Euch gemeinsam auf Abenteuer begebt." }
entries[232344] = { ["name"] = "Vick's VIP Pass", ["text"] = "Einzigartig\nBenutzen: Attune yourself to Blackwing Lair! (30 Sek. Abklingzeit)\n\"For close personal friends of Lord Victor Nefarius only!\"" }
entries[232357] = { ["name"] = "Drachischer Rächer", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n201 - 303 Schaden Tempo 3.50\n(72.00 Schaden pro Sekunde)\n+23 Stärke\n+28 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Verbessert Eure Chance auf Treffer mit allen Zaubern und Angriffen um 2%." }
entries[232358] = { ["name"] = "Leerer Reliquienschrein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 60" }
entries[232373] = { ["name"] = "Veredeltes Auge von Sulfuras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Stimmt Euch auf das innere Feuer ein, damit Ihr Eure Katzengestalt durch ein etwas flammenderes Antlitz ersetzen könnt." }
entries[232389] = { ["name"] = "Buchband der Fülle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nBenötigt Stufe 60\nAnlegen: Euer Zauber 'Kreuzfahrerstoß' stellt zusätzlich 10% Eures maximalen Manas wieder her." }
entries[232390] = { ["name"] = "Götze des himmlischen Fokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht den von 'Sternenregen' verursachten Schaden um 10%, verringert aber den Radius um 50%." }
entries[232391] = { ["name"] = "Götze des Katzenfokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Eure Fähigkeit 'Wilder Biss' wandelt zusätzliche Energie nicht mehr in Schaden um, sondern erstattet bei einem Ausweichen, Fehlschlag oder Parieren 30 Energie." }
entries[232392] = { ["name"] = "Totem des unaufhörlichen Donners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Wenn Ihr einen Schild tragt, erhöht sich die Häufigkeit, mit der Eure Nahkampfangriffe mit 'Waffe des Felsbeißers' die Rune 'Waffe des Mahlstroms' auslösen, um 100 + (5 * Combopunkte)%." }
entries[232409] = { ["name"] = "Totem der Elemente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Euer Talent 'Elementarfokus' hat jetzt maximal 2 Aufladungen und wird bei seiner Auslösung auf 2 Aufladungen gesetzt." }
entries[232414] = { ["name"] = "Drachenhauerklinge", ["text"] = "Questgegenstand\nEinzigartig\nKlassen: Krieger\nBenötigt Stufe 60\nBenutzen: Schneidet eine Schuppe aus Nefarians Haut. Kann nur eingesetzt werden, wenn Nefarian im Kampf beträchtlich geschwächt wurde. (10 Sek. Abklingzeit)" }
entries[232416] = { ["name"] = "Totem des Astralflusses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Erhöht den Angriffskraftbonus von Attacken der Waffe des Windzorns um 68." }
entries[232419] = { ["name"] = "Totem der leitenden Ströme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nBenötigt Stufe 60\nAnlegen: Während 'Frostbrandwaffe' auf Eurer Waffenhandwaffe aktiv ist, verkürzt das Auslösen von 'Wasserschild' die Zauberzeit Eures nächsten Zaubers 'Kettenblitzschlag', der innerhalb von 15 Sek. gewirkt wird, um 20% und erhöht seinen Schaden um 20%. Bis zu 5-mal stapelbar." }
entries[232420] = { ["name"] = "Buchband des Zorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nBenötigt Stufe 60\nAnlegen: Wenn Ihr mit Eurem Zauber 'Heiliger Schock' Schaden verursacht, werden die Zauberzeit und die Manakosten Eures nächsten Einsatzes von 'Heiliger Zorn', der innerhalb von 15 Sek. gewirkt wird, um 20% verringert und dessen Schaden um 20% erhöht. Bis zu 5-mal stapelbar." }
entries[232421] = { ["name"] = "Buchband des Rächens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Buchband\nBenötigt Stufe 60\nAnlegen: Euer 'Schild des Rächers' trifft 2 Ziele weniger, trifft sein Ziel allerdings 2-mal." }
entries[232423] = { ["name"] = "Götze der Pflege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht durch 'Pflege' verursachte Heilung um bis zu 77." }
entries[232424] = { ["name"] = "Götze der Grausamkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Götze\nBenötigt Stufe 60\nAnlegen: Erhöht den von 'Aufschlitzen' zugefügten Anfangsschaden und regelmäßigen Schaden um 7 pro Anwendung." }
entries[232433] = { ["name"] = "Dichter Runenstoffverband", ["text"] = "Benötigt Stufe 50\nBenötigt Erste Hilfe (300)\nBenutzen: Heilt 8 Sek. lang 3400 Schaden." }
entries[232434] = { ["name"] = "Handbuch: Dichter Runenstoffverband", ["text"] = "Benötigt Erste Hilfe (300)\nBenutzen: Lehrt Euch, wie man einen dichten Runenstoffverband herstellt.\nDichter Runenstoffverband\nBenötigt Stufe 50\nBenötigt Erste Hilfe (300)\nBenutzen: Heilt 8 Sek. lang 3400 Schaden.\nBenötigt Schwerer Runenstoffverband (2)" }
entries[232436] = { ["name"] = "Dunkelklauensuppe", ["text"] = "Benötigt Stufe 45\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 2148 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, wird Euer Zauberschaden 10 Min. lang um 12 erhöht." }
entries[232437] = { ["name"] = "Rezept: Dunkelklauensuppe", ["text"] = "Benötigt Kochkunst (300)\nBenutzen: Lehrt Euch, wie man ein Dunkelklauensuppe zubereitet.\nDunkelklauensuppe\nBenötigt Stufe 45\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 2148 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, wird Euer Zauberschaden 10 Min. lang um 12 erhöht.\nBenötigt Dunkelklauenhummer , Trinkbares Weihwasser von Stratholme" }
entries[232438] = { ["name"] = "Geräucherte Rotkieme", ["text"] = "Benötigt Stufe 35\nBenutzen: Stellt im Verlauf von 30 Sek.1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr 10 Sekunden lang esst, wird außerdem die von Euch verursachte Heilung 10 Min. lang um 22 erhöht." }
entries[232443] = { ["name"] = "Rezept: Geräucherte Rotkieme", ["text"] = "Benötigt Kochkunst (300)\nBenutzen: Lehrt Euch, wie man eine geräucherte Rotkieme zubereitet.\nGeräucherte Rotkieme\nBenötigt Stufe 35\nBenutzen: Stellt im Verlauf von 30 Sek.1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr 10 Sekunden lang esst, wird außerdem die von Euch verursachte Heilung 10 Min. lang um 22 erhöht.\nBenötigt Roher Rotkiemen" }
entries[232454] = { ["name"] = "Emblem der wilden Götter", ["text"] = "Accountgebunden\n\"Beweis für die Unterstützung der Abgesandten des Schattenzahns. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\"" }
entries[232455] = { ["name"] = "Emblem der Ehrlosigkeit", ["text"] = "Accountgebunden\n\"Beweis für die Konfrontation mit Illari Dämmerfeder. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\"" }
entries[232456] = { ["name"] = "Emblem des Violetten Auges", ["text"] = "Accountgebunden\n\"Beweis für den Sieg über die Dunklen Reiter. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\"" }
entries[232457] = { ["name"] = "Emblem des Weltenkerns", ["text"] = "Accountgebunden\n\"Beweis für die Einstimmung auf die Leylinienzusammenflüsse. Kann in Hauptstädten bei Runenhändlern eingetauscht werden.\"" }
entries[232458] = { ["name"] = "Rune des verbesserten Refugiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Euren Helm mit der Rune 'Verbessertes Refugium':\n\nErhöht den durch Euren 'Segen des Refugiums' verhinderten Schaden um 100% und erhöht den durch Euren 'Segen des Refugiums' verursachten Schaden um 20% Eures Schildblockwerts.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[232459] = { ["name"] = "Rune der Pyrolyse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Helm mit der Rune 'Pyrolyse':\n\nEure Fähigkeit 'Feuersbrunst' gewährt zusätzlich 15 Sek. lang 30% Zauberwirktempo und verbraucht 'Feuerbrand' nicht mehr.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[232460] = { ["name"] = "Rune der Verzerrung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Armschienen mit der Rune 'Verzerrung':\n\nTeleportiert Euch dahin zurück, wo Ihr zuletzt 'Blinzeln' gewirkt habt, und schließt die Abklingzeit von 'Blinzeln' ab. Lässt sich nur innerhalb von 10 Sek. nach dem Wirken von 'Blinzeln' nutzen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[232461] = { ["name"] = "Rune der Verzweiflung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Armschienen mit der Rune 'Verzweiflung':\n\nDer regelmäßige Schaden Eurer Zauber kann nun kritischen Schaden verursachen und all Eure kritischen Treffer mit Zaubern verursachen 200% mehr Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[232462] = { ["name"] = "Rune der reinigenden Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nPrägt Eure Armschienen mit der Rune 'Reinigende Macht':\n\nVerringert die Abklingzeit von 'Exorzismus' und 'Heiliger Zorn' um 50%. 'Heiliger Zorn' kann jetzt auf jedes Ziel gewirkt werden und betäubt dämonische sowie untote Ziele für 2 Sek.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[232549] = { ["name"] = "Logistikeinsatz VI", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 60" }
entries[232550] = { ["name"] = "Ashkandi, Großschwert der Bruderschaft", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nZweihändig Schwert\n235 - 354 Schaden Tempo 3.60\n(81.81 Schaden pro Sekunde)\n+20 Stärke\n+23 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: +86 Angriffskraft.\n\"Die Initialen A.L. sind in den Schwertgriff eingeätzt.\"" }
entries[232551] = { ["name"] = "Drachischer Schlägel", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nZweihändig Streitkolben\n117 - 176 Schaden Tempo 2.00\n(73.25 Schaden pro Sekunde)\n+33 Stärke\n+21 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nAnlegen: +260 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[232552] = { ["name"] = "Lok'amir il Romathis", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Streitkolben\n47 - 127 Schaden Tempo 2.10\n(41.43 Schaden pro Sekunde)\n+10 Ausdauer\n+18 Intelligenz\n+8 Willenskraft\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 86.\n\"Die Hand von Nefarius.\"" }
entries[232555] = { ["name"] = "Crul'shorukh, Schneide des Chaos", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #668) (1)\nEinhändig Axt\n105 - 197 Schaden Tempo 2.40\n(62.92 Schaden pro Sekunde)\n+13 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nAnlegen: +38 Angriffskraft." }
