entries[232557] = { ["name"] = "Klaue von Chromaggus", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nWaffenhand Dolch\n36 - 89 Schaden Tempo 1.50\n(41.67 Schaden pro Sekunde)\n+7 Ausdauer\n+17 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 68.\nAnlegen: Eure offensiven Zauber erhöhen den Zauberschaden einer zufälligen Magieart 10 Sek. lang um 50. (9.5s Abklingzeit)" }
entries[232558] = { ["name"] = "Chromatisch gehärtetes Schwert", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nEinzigartig anlegbar: (Unbekannt #665) (1)\nEinhändig Schwert\n110 - 205 Schaden Tempo 2.70\n(58.33 Schaden pro Sekunde)\n+14 Stärke\n+15 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60" }
