entries[232606] = { ["name"] = "Ashjre'thul, Armbrust der Pein", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nDistanz Armbrust\n124 - 186 Schaden Tempo 3.40\n(45.59 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nAnlegen: +36 Distanzangriffskraft." }
entries[232607] = { ["name"] = "Herzensbrecher", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nDistanz Bogen\n98 - 183 Schaden Tempo 3.20\n(43.91 Schaden pro Sekunde)\n+6 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nAnlegen: Distanzangriffstreffer haben eine Chance von 2%, einen Zusatzangriff zu gewähren. (Procchance: 2%, 1s Abklingzeit)\nAnlegen: +18 Angriffskraft." }
entries[232608] = { ["name"] = "Drachenodemhandkanone", ["text"] = "Schattenflamme\nWird beim Aufheben gebunden\nDistanz Schusswaffe\n92 - 172 Schaden Tempo 3.00\n(44.00 Schaden pro Sekunde)\n+14 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 60\nBenutzen: Ladet die Handkanone 2,5 Sek. lang auf, um Gegnern in einem kegelförmigen Bereich vor Euch 500 Feuerschaden zuzufügen. Erzeugt ein hohes Maß an Bedrohung. (30 Sek. Abklingzeit)" }
entries[232610] = { ["name"] = "Formel: Prächtiger Trollschein", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigtStamm der Zandalar\n- Wohlwollend\nBenutzen: Lehrt Euch, wie man prächtigen Trollschein herstellt.\nPrächtiger Trollschein\nBenötigt Stufe 45\nBenutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an.\n5 Aufladungen\nBenötigt Fläschchen Mojo (3), Fläschchen großes Mojo (3), Großer glänzender Splitter (2), Magieerfüllte Phiole" }
entries[232611] = { ["name"] = "Prächtiger Trollschein", ["text"] = "Benötigt Stufe 45\nBenutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an.\n5 Aufladungen" }
entries[232652] = { ["name"] = "Zila Amanemodas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Stimmt Euch auf die Dunkelheit in Eurem Innern ein, damit Ihr Euren inneren Dämon besser kontrollieren könnt." }
entries[233197] = { ["name"] = "Trainingshandbuch der Argentumdämmerung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Das Handbuch wird verwendet, um den Argentumknappen für eine Trainingsstunde im Kampf gegen die Silithiden zu rufen. Silithiden, die in Anwesenheit des Knappen getötet werden, steigern Euren Ruf bei der Argentumdämmerung. (5 Min Abklingzeit)\n3 Aufladungen" }
entries[233198] = { ["name"] = "Horn der Dämmerung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Spornt Eure Gruppen- oder Schlachtzugsmitglieder in der Nähe an und gewährt ihnen eine um 10% erhöhte Chance auf kritische Zaubertreffer, eine um 5% erhöhte Chance auf kritische Treffer im Nah- und Distanzkampf und eine um 140 erhöhte Angriffskraft. Hält 2 Stunden lang an. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)" }
entries[233200] = { ["name"] = "Liedblumensaat", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Beschwört eine Liedblume, die 1 Stunde lang bei allen Gruppen- oder Schlachtzugsmitgliedern die kritische Trefferchance von Nahkampf- und Distanzangriffen sowie von Zaubern um 5% und Attribute um 15 erhöht. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)" }
entries[233201] = { ["name"] = "Schimmernde Kugel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Erhöht 2 Stunden lang die Angriffskraft aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs in der Nähe um 200, die Ausdauer um 15% und die kritische Trefferchance von Zaubern 3%. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst. (30 Sek. Abklingzeit)" }
entries[233206] = { ["name"] = "Amboss des Vorarbeiters", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Erhöht die Gesundheit um 300. 15% Tempo für Nahkampfangriffe. 10 Mana alle 5 Sek. Hält 1 Stunde lang an. (30 Sek. Abklingzeit)" }
entries[233208] = { ["name"] = "\"Defekte\" Wahrsagerkugel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Erhöht 2 Stunden lang den verursachten Schaden aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs um 10%. (30 Sek. Abklingzeit)\n\"Egal, wie oft Ihr es schüttelt, das Spielzeug landet immer wieder auf demselben grausigen Schicksal: Schmerzhafter Tod.\"" }
entries[233209] = { ["name"] = "Feuerwasserkessel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Beschwört einen Feuerwasserkessel, der 10 Min. lang bestehen bleibt und von allen Mitgliedern Eurer Gruppe oder Eures Schlachtzugs benutzt werden kann, um 1 Stunde lang die Nahkampfangriffskraft um 35 und die Größe zu erhöhen. (30 Sek. Abklingzeit)" }
entries[233211] = { ["name"] = "Geistschnecke", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Erhöht die Bewegungsgeschwindigkeit aller Gruppen- oder Schlachtzugsmitglieder um 10% und ihre Werte um 15%. Hält 2 Stunden lang an. (30 Sek. Abklingzeit)" }
entries[233213] = { ["name"] = "Uralter Leitstein", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Schwächt die Elementarmitglieder des Abyssischen Rates in Silithus, wodurch der von ihnen verursachte Schaden um 20% verringert wird. Hält 2 Min. lang an. (1 Min Abklingzeit)\n10 Aufladungen" }
entries[233215] = { ["name"] = "Explosive Sandfalle", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Platziert eine Falle an einem Ort in der Nähe, die explodiert, wenn sich ein Silithid des Ashischwarms, Regalschwarms oder Zoraschwarms nähert, wodurch der Silithid 15 Sek. lang alle 3 Sek. Schaden in Höhe von 6% seiner Gesundheit erleidet. (1 Min Abklingzeit)\n10 Aufladungen" }
entries[233216] = { ["name"] = "Frostomatikstrahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Friert einen Silithiden im Bau des Ashischwarms, im Bau des Regalschwarms oder im Bau des Zoraschwarms für 1 Min. ein. Effekt wird durch jeden Schaden unterbrochen. (1 Min Abklingzeit)\n10 Aufladungen" }
entries[233217] = { ["name"] = "Räucherwerk des Tunnelgräbers", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Durch das Einatmen dieses Weihrauchs verschwindet Ihr in die Schatten, was ein unbemerktes Herumschleichen im Bau des Ashischwarms, im Bau des Regalschwarms und im Bau des Zoraschwarms ermöglicht, jedoch wird Eure Geschwindigkeit um 50% verringert. Hält 1 Min. lang an. (1 Min Abklingzeit)\n10 Aufladungen" }
entries[233226] = { ["name"] = "Uraltes Zandalariseil", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Wirft das uralte Seil, um einen Silithiden des Ashischwarms, Regalschwarms oder Zoraschwarms zu fesseln und zu Euch zu ziehen. Kann nicht gegen Gegner eingesetzt werden, die eine höhere Stufe als ( 60 + 1) haben oder als Bossgegner markiert sind. (1 Min Abklingzeit)\n10 Aufladungen\n\"Wurde in längst vergangenen Tagen von Trollen des Zulimperiums im Kampf gegen die Aqir eingesetzt.\"" }
entries[233250] = { ["name"] = "Uralter Zweig", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Verwendet den Zweig, um ein Urtum des Krieges zu rufen, dass Euch beim Kampf gegen Silithiden hilft. (15 Min Abklingzeit)\n3 Aufladungen" }
entries[233351] = { ["name"] = "Hellgrüner Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
