entries[233357] = { ["name"] = "Zwielichtqirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Beschwört eine reitbare Qirajipanzerdrohne oder gibt sie wieder frei. Dies ist ein sehr schnelles Reittier. (3 Sek. Abklingzeit)" }
entries[233358] = { ["name"] = "Gezähmte Silithidendrohne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenutzen: Stößt ein Hochfrequenzsignal aus, das eine Silithidendrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithid gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindselige Handlung gegen den Reiter zwingen die Drohne, sich wieder einzugraben. (3 Sek. Abklingzeit)" }
