entries[233372] = { ["name"] = "Schienbeinschützer des Eroberers", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n604 Rüstung\n+22 Stärke\n+8 Beweglichkeit\n+21 Ausdauer\nHaltbarkeit 75 / 75\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\nAnlegen: Verteidigung +11.\n\nBollwerk des Eroberers (0/5)\nKrone des Eroberers\nSchiftung des Eroberers\nBrustplatte des Eroberers\nBeinschützer des Eroberers\nSchienbeinschützer des Eroberers\n(2) Set : Verringert die Abklingzeit von 'Donnerknall' um 100%.\n(4) Set : Euer 'Schildschlag' verursacht 100% mehr Bedrohung und seine Abklingzeit wird abgeschlossen, wenn er pariert oder geblockt wird oder ihm ausgewichen wird." }
entries[233373] = { ["name"] = "Brustplatte des Eroberers", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n985 Rüstung\n+30 Stärke\n+15 Beweglichkeit\n+38 Ausdauer\nHaltbarkeit 165 / 165\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Verteidigung +16.\n\nBollwerk des Eroberers (0/5)\nKrone des Eroberers\nSchiftung des Eroberers\nBrustplatte des Eroberers\nBeinschützer des Eroberers\nSchienbeinschützer des Eroberers\n(2) Set : Verringert die Abklingzeit von 'Donnerknall' um 100%.\n(4) Set : Euer 'Schildschlag' verursacht 100% mehr Bedrohung und seine Abklingzeit wird abgeschlossen, wenn er pariert oder geblockt wird oder ihm ausgewichen wird." }
